mapper.update:
UPDATE tb_screen_consume
SET inbound_number = inbound_number + #{number},
    current_number = current_number + #{number}
WHERE id = #{id}
  AND deleted = 0

UPDATE tb_screen_consume
SET current_number = current_number - #{number}
WHERE id = #{id}
  AND deleted = 0

mapper.select:
SELECT count(*)
FROM tb_screen_consume
WHERE deleted = 0
  AND reagent_id = #{reagentId}
  AND consume_order = #{consumeOrder}
  AND bath_number = #{bathNumber}
  AND indate = #{indate}
  AND manufacture_date = #{manufactureDate}
  AND dept_id = #{deptId}

SELECT count(*)
FROM tb_screen_consume
WHERE deleted = 0
  AND reagent_name = #{reagentName}
  AND consume_order = #{consumeOrder}
  AND bath_number = #{bathNumber}
  AND indate = #{indate}
  AND manufacture_date = #{manufactureDate}
  AND dept_id = #{deptId}

SELECT reagent_name, bath_number, IFNULL(SUM(tscd.change_number), 0) AS currentNumber FROM tb_screen_consume AS tsc LEFT JOIN tb_screen_consume_record AS tscd ON tsc.id = tscd.consume_id WHERE tsc.deleted = 0 AND tscd.deleted = 0 AND tscd.type in (1, 3) AND tsc.dept_id = #{deptId}
AND tscd.create_time BETWEEN #{startDateTime} AND #{endDateTime}
AND tsc.reagent_name like CONCAT('%', #{reagentName}, '%') GROUP BY reagent_name, bath_number
